css:
.fx-cs{--mx:50%;--my:42%;position:relative;overflow:hidden;min-height:100vh;background:var(--surface)}
.fx-cs .lay{min-height:100vh;display:grid;gap:1.1em;justify-items:center;align-content:center;text-align:center;padding:2em}
.fx-cs .lay>*{max-width:40ch}
.fx-cs .base{color:color-mix(in srgb,var(--text) 16%,var(--surface))}
.fx-cs .base em,.fx-cs .base b{color:inherit}
.fx-cs .lit{position:absolute;inset:0;pointer-events:none;color:var(--text);
background:radial-gradient(circle 14em at var(--mx) var(--my),color-mix(in srgb,var(--accent) 20%,transparent),transparent 100%);
-webkit-mask-image:radial-gradient(circle 14em at var(--mx) var(--my),#000 22%,transparent 100%);mask-image:radial-gradient(circle 14em at var(--mx) var(--my),#000 22%,transparent 100%)}
.fx-cs h1{font-size:clamp(2.4em,6.4vw,4.4em);max-width:14ch}.fx-cs em{font-style:italic;color:var(--accent)}
.fx-cs .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase}
.fx-cs .lit .eye{color:var(--accent)}
.fx-cs p{font-size:1.1em;max-width:36ch}
.fx-cs ul{list-style:none;margin:.6em 0 0;padding:0;display:grid;gap:.5em;font-size:1.05em}.fx-cs li b{font-family:var(--font-heading);margin-right:.7em;opacity:.7}
@media(hover:none),(pointer:coarse){.fx-cs .lit{-webkit-mask-image:none;mask-image:none;background:none}.fx-cs .base{visibility:hidden}}
.fx-cs{touch-action:pan-y}

js:
(function(){document.querySelectorAll('.fx-cs').forEach(function(r){
if(!matchMedia('(hover:hover) and (pointer:fine)').matches)return;
r.addEventListener('pointermove',function(e){if(e.pointerType==='touch')return;var b=r.getBoundingClientRect();r.style.setProperty('--mx',(e.clientX-b.left)+'px');r.style.setProperty('--my',(e.clientY-b.top)+'px')})})})();
/* touch: spotlight jumps to the tap and follows a drag */
if(!matchMedia('(hover:hover) and (pointer:fine)').matches){document.querySelectorAll('.fx-cs').forEach(function(r){function m(e){var b=r.getBoundingClientRect();r.style.setProperty('--mx',(e.clientX-b.left)+'px');r.style.setProperty('--my',(e.clientY-b.top)+'px')}
r.addEventListener('pointerdown',m);r.addEventListener('pointermove',function(e){if(e.pointerType==='touch')m(e)})})}
